 "content": "from collections import Counter


def _runs(mask):
    out = []
    start = None
    for i, yes in enumerate(mask + [False]):
        if yes and start is None:
            start = i
        elif not yes and start is not None:
            out.append((start, i))
            start = None
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_runs = _runs([any(v != 0 for v in row) for row in grid])
    col_runs = _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])

    cores = []
    for r0, r1 in row_runs:
        for c0, c1 in col_runs:
            # Ignore clipped edge fragments; the repeated motifs have an outer border.
            if r1-r0 < 3 or c1-c0 < 3:
                continue
            perimeter = []
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if r in (r0, r1-1) or c in (c0, c1-1):
                        if grid[r][c] != 0:
                            perimeter.append(grid[r][c])
            if not perimeter:
                continue
            frame = Counter(perimeter).most_common(1)[0][0]
            for r in range(r0+1, r1-1):
                for c in range(c0+1, c1-1):
                    if grid[r][c] != 0 and grid[r][c] != frame:
                        cores.append((r, c, grid[r][c]))

    counts = Counter(color for _, _, color in cores)
    if not counts:
        return out
    base = counts.most_common(1)[0][0]
    sources = [(r, c, color) for r, c, color in cores if color != base]
    for r, c, color in sources:
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out

