 "content": "from collections import Counter


def transform(grid):
    """Fill blank gaps between collinear occurrences of minority motif colors."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    motif_counts = Counter(v for row in grid for v in row if v not in (0, frame))
    if not motif_counts:
        return out
    common = motif_counts.most_common(1)[0][0]
    rare_colors = set(motif_counts) - {common}

    # Between aligned matching motifs, paint only zero cells. Other tiles and
    # their frames remain intact while the same-color line spans their gutters.
    for color in rare_colors:
        for r in range(h):
            positions = [c for c in range(w) if grid[r][c] == color]
            if len(positions) >= 2:
                for c in range(min(positions), max(positions) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for c in range(w):
            positions = [r for r in range(h) if grid[r][c] == color]
            if len(positions) >= 2:
                for r in range(min(positions), max(positions) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out


