def transform(grid):
    """Join distinct matching motif objects along their shared row/column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    motif_counts = Counter(v for row in grid for v in row if v not in (0, frame))
    if not motif_counts:
        return out
    common = motif_counts.most_common(1)[0][0]
    rare = set(motif_counts) - {common}

    # Label separate 4-connected objects of rare colors. Same-color pixels
    # inside one solid tile are one marker, not independent endpoints.
    labels = {}
    next_id = 0
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in rare or (r, c) in labels:
                continue
            next_id += 1
            labels[(r, c)] = next_id
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color
                            and (nr, nc) not in labels):
                        labels[(nr, nc)] = next_id
                        q.append((nr, nc))

    for color in rare:
        for r in range(h):
            positions = [(c, labels[(r,c)]) for c in range(w)
                         if grid[r][c] == color]
            # Pair only cells belonging to different matching objects.
            for i, (c1, id1) in enumerate(positions):
                for c2, id2 in positions[i+1:]:
                    if id1 != id2:
                        for c in range(c1+1, c2):
                            if grid[r][c] == 0:
                                out[r][c] = color
        for c in range(w):
            positions = [(r, labels[(r,c)]) for r in range(h)
                         if grid[r][c] == color]
            for i, (r1, id1) in enumerate(positions):
                for r2, id2 in positions[i+1:]:
                    if id1 != id2:
                        for r in range(r1+1, r2):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out


