def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    interiors = Counter(v for row in grid for v in row if v not in (0, frame))
    if not interiors:
        return out
    max_count = max(interiors.values())
    common = {v for v, n in interiors.items() if n == max_count}
    # Tied interior colors are ordinary alternating fills; only a unique
    # minority color acts as the marker/projector.
    markers = set(interiors) - common if len(common) == 1 else set()
    if not markers:
        return out

    row_runs = _runs([any(v != 0 for v in row) for row in grid])
    col_runs = _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    tiles = {}
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            if r1-r0 < 3 or c1-c0 < 3:
                continue
            boundary = [grid[r][c] for r in range(r0,r1) for c in range(c0,c1)
                        if r in (r0,r1-1) or c in (c0,c1-1)]
            if not boundary or Counter(boundary).most_common(1)[0][0] != frame:
                continue
            tiles[ri,ci] = (r0,r1,c0,c1)

    # Match marker cells by the same relative interior coordinate in adjacent
    # framed tiles, then color only the intervening zero gutter.
    for (ri,ci),(r0,r1,c0,c1) in tiles.items():
        for dr,dc in ((0,1),(1,0)):
            other = tiles.get((ri+dr,ci+dc))
            if other is None:
                continue
            rr0,rr1,cc0,cc1 = other
