 "content": "from collections import Counter


def _runs(flags):
    out, start = [], None
    for i, flag in enumerate(flags + [False]):
        if flag and start is None:
            start = i
        elif not flag and start is not None:
            out.append((start, i))
            start = None
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    frame_counts = Counter(v for row in grid for v in row if v != 0)
    if not frame_counts:
        return out
    frame = frame_counts.most_common(1)[0][0]
    row_runs = _runs([any(v != 0 for v in row) for row in grid])
    col_runs = _runs([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    tiles = {}
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            if r1-r0 < 3 or c1-c0 < 3:
                continue
            edge = [grid[r][c] for r in range(r0,r1) for c in range(c0,c1)
                    if r in (r0,r1-1) or c in (c0,c1-1)]
            if not edge or Counter(edge).most_common(1)[0][0] != frame:
                continue
            color = grid[(r0+r1-1)//2][(c0+c1-1)//2]
            if color not in (0, frame):
                tiles[ri,ci] = (r0,r1,c0,c1,color)
    # Connect centers of same-colored neighboring tiles through their separator,
    # including tile borders along the line.
    for (ri,ci),(r0,r1,c0,c1,color) in tiles.items():
        other = tiles.get((ri,ci+1))
        if other and other[4] == color:
            rr0,rr1,cc0,cc1,_=other
            row=(r0+r1-1)//2
            for c in range(c1-1,cc0+1):
                out[row][c]=color
        other = tiles.get((ri+1,ci))
        if other and other[4] == color:
            rr0,rr1,cc0,cc1,_=other
            col=(c0+c1-1)//2
            for r in range(r1-1,rr0+1):
                out[r][col]=color
    return out


if __name__ == '__main__':
    pass
