    # Identify framed-tile center colors and their center coordinates.
    centers = {}
    for ri, r0 in enumerate(row_starts):
        if r0 + 2 >= h or r0 % 7 != 1:
            continue
        for ci, c0 in enumerate(col_starts):
            if c0 + 2 >= w or c0 % 7 != 1:
                continue
            color = grid[r0 + 2][c0 + 2]
            if color not in (0, 4):
                centers[ri, ci] = (r0 + 2, c0 + 2, color)
    frequencies = Counter(v[2] for v in centers.values())
    if not frequencies:
        return out
    largest = max(frequencies.values())
    common = {c for c, n in frequencies.items() if n == largest}
    markers = set(frequencies) - common if len(common) == 1 else set(frequencies)
    for color in markers:
        for r in range(h):
            xs = [c for (ri,ci),(rr,c,color0) in centers.items() if color0 == color and rr == r]
            if len(xs) > 1:
                for c in range(min(xs), max(xs)+1):
                    out[r][c] = color
        for c in range(w):
            ys = [r for (ri,ci),(r,cc,color0) in centers.items() if color0 == color and cc == c]
            if len(ys) > 1:
                for r in range(min(ys), max(ys)+1):
                    out[r][c] = color
    return out


