def transform(grid):
    """Connect equal-colored tile centers along their shared row/column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The tiling is identified by nonzero bands separated by zero gutters.
    row_bands, col_bands = [], []
    for flags, target in (([any(row) for row in grid], row_bands),
                          ([any(grid[r][c] for r in range(h)) for c in range(w)], col_bands)):
        start = None
        for i, flag in enumerate(flags + [False]):
            if flag and start is None:
                start = i
            elif not flag and start is not None:
                target.append((start, i))
                start = None
    counts = Counter(v for row in grid for v in row if v)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    tiles = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            if r1-r0 < 3 or c1-c0 < 3:
                continue
            edge = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                    if r in (r0, r1-1) or c in (c0, c1-1)]
            if not edge or Counter(edge).most_common(1)[0][0] != frame:
                continue
            color = grid[(r0+r1-1)//2][(c0+c1-1)//2]
            if color not in (0, frame):
                tiles[ri, ci] = color
    for (ri, ci), color in tiles.items():
        # horizontally connect same-color neighbors, center row only
        if tiles.get((ri, ci+1)) == color:
            r0, r1 = row_bands[ri]
            left_end, right_start = col_bands[ci][1], col_bands[ci+1][0]
            r = (r0+r1-1)//2
            for c in range(left_end, right_start):
                if grid[r][c] == 0:
                    out[r][c] = color
        # vertically connect same-color neighbors, center column only
        if tiles.get((ri+1, ci)) == color:
            c0, c1 = col_bands[ci]
            top_end, bottom_start = row_bands[ri][1], row_bands[ri+1][0]
            c = (c0+c1-1)//2
            for r in range(top_end, bottom_start):
                if grid[r][c] == 0:
                    out[r][c] = color
    return out


