 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Tile centers lie at the centers of the repeated framed objects.
    centers = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 4):
                continue
            # center pixels are aligned on the repeating 7-cell lattice
            if r % 7 == 3 and c % 7 == 3:
                centers[r, c] = color
    counts = Counter(centers.values())
    if not counts:
        return out
    most = max(counts.values())
    common = {color for color, n in counts.items() if n == most}
    markers = set(counts) - common if len(common) == 1 else set(counts)

    # Draw straight centerlines between repeated marker centers, continuing
    # across intervening panels and gutters.
    for color in markers:
        for r in range(h):
            xs = [c for (rr, c), col in centers.items() if rr == r and col == color]
            if len(xs) > 1:
                for c in range(min(xs), max(xs) + 1):
                    out[r][c] = color
        for c in range(w):
            ys = [r for (r, cc), col in centers.items() if cc == c and col == color]
            if len(ys) > 1:
                for r in range(min(ys), max(ys) + 1):
                    out[r][c] = color
    return out


