  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     g[r][c]=4 if dr in (0,4) or dc in (0,4) else (vals[i][j] if i<4 and j<4 else 0)
# For each motif center, extend along cardinal ray to next nonzero cell;
# source colors recur in every tile, so lines color the existing intervening motifs too.
out=[row[:] for row in g]
