 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]
    # Identify the most frequent non-frame interior color as the background
    # motif; other tile colors are the projecting markers.
    tile_colors = [grid[r][c] for r in range(3, h, 7) for c in range(3, w, 7)
                   if grid[r][c] not in (0, frame)]
    if not tile_colors:
        return out
    freq = Counter(tile_colors)
    common = max(freq, key=freq.get)
    markers = set(freq) - {common}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in markers:
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out


if __name__ == '__main__':
    pass
