 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect repeated framed tile lattice; these tiles are 5x5 with pitch 7.
    starts_r = list(range(1, h, 7))
    starts_c = list(range(1, w, 7))
    colors = {}
    for i, r0 in enumerate(starts_r):
        for j, c0 in enumerate(starts_c):
            r, c = r0 + 2, c0 + 2
            if r < h and c < w and grid[r][c] not in (0, 4):
                colors[i, j] = grid[r][c]
    freq = Counter(colors.values())
    if not freq:
        return out
    base = freq.most_common(1)[0][0]
    markers = set(freq) - {base}
    # Like exceptional motifs continue through the gap between adjacent tiles;
    # carry the motif's full three-cell thickness through the two-cell gutter.
    for (i, j), color in colors.items():
        if color not in markers:
            continue
        if colors.get((i, j + 1)) == color and j + 1 < len(starts_c):
            for r in range(starts_r[i] + 1, min(starts_r[i] + 4, h)):
                for c in range(starts_c[j] + 5, starts_c[j + 1]):
                    if grid[r][c] == 0:
                        out[r][c] = color
        if colors.get((i + 1, j)) == color and i + 1 < len(starts_r):
            for c in range(starts_c[j] + 1, min(starts_c[j] + 4, w)):
                for r in range(starts_r[i] + 5, starts_r[i + 1]):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out


if __name__ == '__main__':
    pass
